#!/usr/bin/env python3
"""Merge user data from JSON, CSV and Parquet sources by user_id.

Priority: source_a > source_b > source_c.
"""

import json
import math
from datetime import date, datetime

import pandas as pd

SOURCES = [
    ("source_a", "/data/source_a/users.json"),
    ("source_b", "/data/source_b/users.csv"),
    ("source_c", "/data/source_c/users.parquet"),
]

ALIASES = {
    "user_id": {"user_id", "id", "userid"},
    "email": {"email", "email_address"},
    "name": {"full_name", "name", "username"},
    "created_date": {"registration_date", "created_at", "joined"},
    "status": {"status", "is_active", "active"},
}

COLUMNS = ["user_id", "name", "email", "created_date", "status"]


def read_source(name, path):
    if name == "source_a":
        with open(path, encoding="utf-8") as fh:
            data = json.load(fh)
        if isinstance(data, dict):
            data = data.get("users", data)
        return pd.DataFrame(data)
    if name == "source_b":
        return pd.read_csv(path)
    return pd.read_parquet(path)


def rename_columns(df):
    lookup = {}
    for canonical, aliases in ALIASES.items():
        for alias in aliases:
            lookup[alias] = canonical
    mapping = {}
    for col in df.columns:
        canonical = lookup.get(str(col).strip().lower())
        if canonical and canonical not in mapping.values():
            mapping[col] = canonical
    return df.rename(columns=mapping)


def is_present(value):
    if value is None:
        return False
    if isinstance(value, float) and math.isnan(value):
        return False
    if value is pd.NA or value is pd.NaT:
        return False
    return str(value).strip() != ""


def clean_text(value):
    return str(value).strip()


def normalize_date(value):
    if isinstance(value, (datetime, date)):
        return value.strftime("%Y-%m-%d")
    text = clean_text(value)
    parsed = pd.to_datetime(text, errors="coerce")
    if pd.isna(parsed):
        return text
    return parsed.strftime("%Y-%m-%d")


def normalize_status(value):
    if isinstance(value, bool):
        return "active" if value else "inactive"
    text = clean_text(value)
    lowered = text.lower()
    if lowered in {"true", "1", "active", "yes"}:
        return "active"
    if lowered in {"false", "0", "inactive", "no"}:
        return "inactive"
    return text


def normalize_value(field, value):
    if field == "created_date":
        return normalize_date(value)
    if field == "status":
        return normalize_status(value)
    return clean_text(value)


def to_user_id(value):
    number = pd.to_numeric(value, errors="coerce")
    if pd.isna(number):
        return None
    return int(number)


def main():
    per_source = {}
    for name, path in SOURCES:
        df = rename_columns(read_source(name, path))
        records = {}
        for _, row in df.iterrows():
            uid = to_user_id(row.get("user_id"))
            if uid is None:
                continue
            record = {}
            for field in COLUMNS[1:]:
                if field in df.columns and field in row.index and is_present(row[field]):
                    record[field] = normalize_value(field, row[field])
            records[uid] = record
        per_source[name] = records

    source_names = [name for name, _ in SOURCES]
    all_ids = sorted({uid for records in per_source.values() for uid in records})

    merged_rows = []
    conflicts = []
    for uid in all_ids:
        row = {"user_id": uid}
        for field in COLUMNS[1:]:
            values = {}
            for source in source_names:
                record = per_source[source].get(uid)
                if record and field in record:
                    values[source] = record[field]

            if not values:
                row[field] = None
                continue

            ordered = [values[s] for s in source_names if s in values]
            selected = ordered[0]
            row[field] = selected

            if len(set(ordered)) > 1:
                conflicts.append(
                    {
                        "user_id": uid,
                        "field": field,
                        "values": {s: values[s] for s in source_names if s in values},
                        "selected": selected,
                    }
                )
        merged_rows.append(row)

    merged = pd.DataFrame(merged_rows, columns=COLUMNS)
    merged["user_id"] = merged["user_id"].astype("int64")
    for field in COLUMNS[1:]:
        merged[field] = merged[field].astype("string")
    merged.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w", encoding="utf-8") as fh:
        json.dump(report, fh, indent=2, ensure_ascii=False)
        fh.write("\n")

    print(f"Merged {len(merged)} users, {len(conflicts)} conflicts")


if __name__ == "__main__":
    main()

